# All four failure categories can produce the identical surface symptom:
# "the model's real-world accuracy just dropped."

def diagnose(symptom):
    if is_service_erroring(symptom):
        return "infrastructure failure -- fix like any software incident"
    if input_distribution_shifted(symptom) and not relationship_changed(symptom):
        return "data drift -- likely fixable by retraining on recent data"
    if relationship_changed(symptom):
        return "concept drift -- may need a different model or features"
    if upstream_pipeline_is_silently_broken(symptom):
        return "upstream pipeline failure -- fix at the source, not the model"
