def monitoring_snapshot(service, predictions, sampled_outcomes):
    return {
        "operational": {
            "latency_p95": service.latency_p95(),
            "error_rate": service.error_rate(),
        },
        "prediction_level": {
            "class_distribution": prediction_distribution(predictions),
            "confidence_shift": confidence_shift(predictions),
        },
        "outcome_based": (
            compute_eval_metrics(predictions, sampled_outcomes)  # ML course metrics
            if sampled_outcomes else "awaiting ground truth"
        ),
    }

# Fast layers (operational, prediction-level) flag something worth
# investigating immediately; the slow layer (outcome-based) confirms
# whether it was actually a real problem, once ground truth arrives.
