def on_monitoring_signal(signal, stakes_level):
    if not signal.crosses_threshold():
        return "no action"

    alert_team(signal)

    if signal.category == "data_drift":
        new_model, metrics = ml_ci_cd_pipeline(fetch_recent_data())  # module 3
        if metrics["precision"] < PROMOTION_THRESHOLD:
            return "retrained model did not clear evaluation gate"
        if stakes_level == "high":
            return "awaiting human approval before promotion"
        return rollout_new_version(new_model, current_model, router)

    return "concept drift or upstream failure -- needs investigation, not just retraining"
